INSERT INTO `items` (`id`, `name`, `code`, `description`, `unit`, `price`, `gst_rate`, `created_at`) VALUES (2, 'Hybrid AI Chatbot', '', 'Customer asks a question naturally.
The chatbot first searches your predefined knowledge base (FAQs, visa rules, packages, pricing, etc.).
If a matching answer exists, it replies with that approved answer.
If no match is found, AI generates a response using only your business information.
If the query is complex, it collects the customer\'s details and creates a lead.
The lead is emailed to your team and the customer receives a thank-you message with your contact details.', '1', 20000, NULL, '2026-07-18 09:47:42');
