INSERT INTO `estimate_lines` (`id`, `estimate_id`, `item_id`, `name`, `description`, `quantity`, `price`, `gst_rate`, `amount`) VALUES (1, 1, 4, 'Website Redesign', '• Complete UI/UX redesign
