INSERT INTO `estimate_lines` (`id`, `estimate_id`, `item_id`, `name`, `description`, `quantity`, `price`, `gst_rate`, `amount`) VALUES (21, 11, 14, 'Other Features', '<h3>1. Inventory Management</h3><ul data-spread="false"><li>Master inventory/parts database</li><li>Category-wise material management</li><li>Part name, drawing number, material grade, diameter, length and other specifications</li><li>Current stock quantity</li><li>Stock IN / Stock OUT</li><li>Automatic stock balance</li><li>Low-stock identification</li><li>Inventory transaction history</li><li>Search and filter inventory records</li></ul><h3>2. Material Planner</h3><ul data-spread="false"><li>Material requirement calculation</li><li>Filter materials by category</li><li>Select parts from Master Part List</li><li>Automatically calculate total material requirement</li><li>Compare required quantity against available stock</li><li>Identify shortage quantities</li><li>Save new Master Parts</li><li>Material planning based on production requirements</li></ul><h3>3. Machine Assembly – BOM</h3><ul data-spread="false"><li>Create and manage machines</li><li>Add multiple parts/components to a machine</li><li>Define required quantity of every component</li><li>Display current stock against BOM requirement</li><li>Automatically calculate <strong>“Can Build Now”</strong> quantity</li><li>Maintain <strong>Total Built</strong> machine count</li><li>Build Machine function</li><li>Machine-wise production/build history</li><li>Full Build Report</li></ul><h3>4. Vendor Management</h3><ul data-spread="false"><li>Create and manage multiple vendors</li><li>Vendor company/contact details</li><li>Assign materials/parts to vendors</li><li>Vendor-wise purchase history</li><li>Maintain purchase rates</li><li>Vendor ledger/history</li></ul><h3>5. Reports &amp; Dashboard</h3><ul data-spread="false"><li>Current inventory report</li><li>Stock movement report</li><li>Low-stock/shortage report</li><li>Material requirement report</li><li>Consolidated purchasing report</li><li>Machine BOM report</li><li>Machine build report</li><li>Vendor purchase report</li><li>Vendor-wise billing report</li><li>Date-wise transaction reports</li></ul><h3>6. CRM / Administration</h3><ul data-spread="false"><li>Secure admin login</li><li>Dashboard</li><li>User management</li><li>Role-based access where required</li><li>Centralized data management</li><li>Search, filters and reporting<br><br>Terms &amp; Conditions</li><li>50% advance payment to start development</li><li>50% on final completion and deployment</li><li>SMS, WhatsApp API or other third-party service charges are not included unless specifically mentioned.</li><li>Additional features outside the approved scope will be quoted separately.</li><li>Responsive interface for desktop/tablet use<br><br></li></ul>', 1, 15000, 18, 15000);

